 "<b style=\"font-size:27px;color:#2f8f9d\">Para quién</b><br><span style=\"font-size:22px;color:#2b1b20\">Alumnado de 12 a 16 años.</span>": "<b style=\"font-size:27px;color:#2f8f9d\">Norentzat</b><br><span style=\"font-size:22px;color:#2b1b20\">12 eta 16 urte arteko ikasleak.</span>",
 "<b style=\"font-size:27px;color:#af8336\">Dónde</b><br><span style=\"font-size:22px;color:#2b1b20\">Pasillos, en vertical, A3.</span>": "<b style=\"font-size:27px;color:#af8336\">Non</b><br><span style=\"font-size:22px;color:#2b1b20\">Korridoreetan, bertikalean, A3.</span>",
